window.portfolioProjects = [{"id":"road","category":"ai","type":"Computer vision / ML","year":"2026 · Ongoing","title":"Road accident-risk warning","summary":"A roadside prototype that reads traffic footage and classifies accident-risk types using computer vision and machine learning.","role":"Project manager & primary developer · Team of three","tags":["Python","YOLO","LightGBM","OpenCV"],"image":"assets/road-thumbnail.png","imageAlt":"Senior-project traffic detection output with vehicle boxes and a blue road-region boundary","imageCaption":"Actual prototype output","href":"work/road-risk.html"},{"id":"booking","category":"software","type":"Web / Mobile","year":"2025","title":"University room booking","summary":"A web and mobile system for finding rooms, making reservations, and managing approvals for students, lecturers, and staff.","role":"One of the primary developers","tags":["Node.js","MySQL","Flutter"],"visual":"booking","details":"\u003cp>The project started as a web application and was later extended into a Flutter mobile app using the same backend.\u003c/p>\u003ch3>My contribution\u003c/h3>\u003cp>I worked on the interface, application functionality, backend integration, and testing. I also tested mobile booking flows on an iOS simulator.\u003c/p>\u003ch3>How it works\u003c/h3>\u003cp>Students browse rooms and request a booking. Role-based approval flows let lecturers and staff review reservations and manage access. Node.js, Express, and MySQL support the backend; Flutter provides the mobile interface.\u003c/p>\u003cp>This was an academic team project, not a university-wide production deployment. The graphic on this portfolio is an explanatory illustration.\u003c/p>\u003cp>\u003ca href='https://github.com/Zenzee7711/library-room-reservation-web' target='_blank' rel='noopener noreferrer'>Web repository \u003csvg class='ico' viewBox='0 0 16 16' fill='none' stroke='currentColor' stroke-width='1.6' stroke-linecap='round' stroke-linejoin='round' aria-hidden='true'>\u003cpath d='M4.5 11.5 11.5 4.5M6.2 4.5h5.3v5.3'/>\u003c/svg>\u003c/a> &nbsp; \u003ca href='https://github.com/Zenzee7711/library-room-booking-mobile' target='_blank' rel='noopener noreferrer'>Mobile repository \u003csvg class='ico' viewBox='0 0 16 16' fill='none' stroke='currentColor' stroke-width='1.6' stroke-linecap='round' stroke-linejoin='round' aria-hidden='true'>\u003cpath d='M4.5 11.5 11.5 4.5M6.2 4.5h5.3v5.3'/>\u003c/svg>\u003c/a>\u003c/p>"},{"id":"flight","category":"ai","type":"Data / Machine learning","year":"2026 · Course project","title":"Flight-delay analytics","summary":"Flight-delay classification on roughly 450,000 historical records, connected to a Kafka streaming prediction prototype.","role":"Model training, evaluation & testing","tags":["PySpark","Spark MLlib","Kafka"],"visual":"flight","details":"\u003cp>A Big Data Management and Analytics team project using PySpark and Spark MLlib to explore flight-delay classification.\u003c/p>\u003ch3>My contribution\u003c/h3>\u003cp>I trained, evaluated, and tested classification models and tested the streaming prediction path. Teammates led data cleaning, feature engineering, and Kafka producer/consumer integration.\u003c/p>\u003ch3>What we compared\u003c/h3>\u003cp>Logistic regression, decision trees, random forests, and gradient-boosted trees were evaluated with different class-balancing strategies. Delayed flights were the minority class, so PR-AUC was more useful than reporting accuracy alone.\u003c/p>\u003cp>The selected approach was gradient-boosted trees with oversampling. This was a completed course project and streaming prototype.\u003c/p>"},{"id":"robot","category":"hardware","type":"Hardware / Prototyping","year":"2026 · Ongoing","title":"Ka-Naung robotic dog","summary":"A collaborative robot-dog prototype. My part is testing servos, assessing power requirements, and helping assemble the hardware.","role":"Hardware development & testing","tags":["MG995 servos","Power budgeting","Soldering"],"visual":"robot","details":"\u003cp>Ka-Naung Pet Dog is an ongoing team hardware project.\u003c/p>\u003ch3>My contribution\u003c/h3>\u003cul>\u003cli>Testing MG995 servo motors for correct operation.\u003c/li>\u003cli>Evaluating power requirements, battery capacity, and suitable battery types.\u003c/li>\u003cli>Helping with soldering, assembly, and PCB and remote-control connection planning.\u003c/li>\u003c/ul>\u003cp>My work focuses on hardware development and testing. The robot is still a collaborative prototype, rather than a finished product.\u003c/p>"}];
